package alert

import (
	"encoding/json"
	"errors"
	"net/http"
	"net/url"
)

type Controller struct {
	service *Service
}

func NewController(service *Service) *Controller {
	return &Controller{service: service}
}

// @Summary List alerts
// @Description Retrieve alerts generated by samples outside their station thresholds
// @Tags alerts
// @Produce json
// @Param station_id query string false "Station ID (hexadecimal ObjectID)"
// @Success 200 {array} Alert
// @Failure 400 {object} map[string]string "Invalid station ID"
// @Failure 500 {object} map[string]string "Internal Server Error"
// @Router /alerts [get]
func (c *Controller) GetAll(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	query, err := url.ParseQuery(r.URL.RawQuery)
	if err != nil {
		w.WriteHeader(http.StatusBadRequest)
		_ = json.NewEncoder(w).Encode(map[string]string{"error": ErrInvalidStationID.Error()})
		return
	}
	alerts, err := c.service.List(r.Context(), query.Get("station_id"))
	if err != nil {
		status := http.StatusInternalServerError
		if errors.Is(err, ErrInvalidStationID) {
			status = http.StatusBadRequest
		}
		w.WriteHeader(status)
		_ = json.NewEncoder(w).Encode(map[string]string{"error": err.Error()})
		return
	}
	_ = json.NewEncoder(w).Encode(alerts)
}
